INSERT INTO pull_task_group_account (
  task_id, group_execution_id, account_id, account_phone, role_type, role_seq,
  source_type, selection_mode, entry_mode, membership_status, admin_status,
  availability_status, pull_call_id, occupied_at, created_at, updated_at
) VALUES (
  #{taskId}, #{groupExecutionId}, #{accountId}, #{accountPhone}, #{roleType}, #{roleSeq},
  #{sourceType}, #{selectionMode}, #{entryMode}, #{membershipStatus},
  #{adminStatus}, #{availabilityStatus}, #{pullCallId}, #{occupiedAt},
  #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT *
FROM pull_task_group_account
WHERE group_execution_id = #{groupExecutionId}
  AND role_type = #{roleType}
ORDER BY role_seq ASC

SELECT *
FROM pull_task_group_account
WHERE account_id = #{accountId}
  AND role_type = #{roleType}
  AND released_at IS NULL
ORDER BY id ASC

SELECT *
FROM pull_task_group_account
WHERE group_execution_id = #{groupExecutionId}
  AND role_type = #{guard.participantRole}
  AND availability_status = #{guard.availabilityStatus}
  AND membership_status = #{guard.expectedStatus}
  AND pull_call_id IS NULL
  AND active_pull_attempt_id IS NULL
  AND membership_failure_count < #{guard.maxFailureCount}
ORDER BY role_seq ASC
LIMIT #{limit}

SELECT role_type AS roleType, COUNT(*) AS availableCount
FROM pull_task_group_account
WHERE group_execution_id = #{groupExecutionId}
  AND availability_status = #{availabilityStatus}
GROUP BY role_type

