UPDATE pull_task_group_account
SET membership_status = #{transition.targetStatus},
    membership_reason_code = #{transition.result.reasonCode},
    membership_reason_message = #{transition.result.reasonMessage},
    membership_result_at =

      #{transition.now}
      membership_result_at
    ,
    joined_at = COALESCE(#{transition.result.occurredAt}, joined_at),
    updated_at = #{transition.now}
WHERE id = #{transition.id}
  AND membership_status IN
  #{status}

UPDATE pull_task_group_account
SET pull_call_id = #{binding.scope.pullCallId},
    updated_at = #{binding.scope.now}
WHERE id = #{binding.scope.roleRowId}
  AND role_type = #{binding.expected.roleType}
  AND source_type = #{binding.expected.sourceType}
  AND availability_status = #{binding.expected.availabilityStatus}
  AND pull_call_id IS NULL

UPDATE pull_task_group_account
SET pull_call_id = #{binding.pullCallId},
    membership_status = #{guard.targetStatus},
    active_pull_attempt_id = #{binding.attemptId},
    membership_reason_code = NULL,
    membership_reason_message = NULL,
    membership_result_at = NULL,
    updated_at = #{binding.now}
WHERE id = #{binding.participantId}
  AND role_type = #{guard.participantRole}
  AND availability_status = #{guard.availabilityStatus}
  AND membership_status = #{guard.expectedStatus}
  AND pull_call_id IS NULL
  AND active_pull_attempt_id IS NULL
  AND membership_failure_count < #{guard.maxFailureCount}

UPDATE pull_task_group_account
SET last_puller_group_account_id = #{binding.pullerGroupAccountId},
    updated_at = #{binding.now}
WHERE id = #{binding.participantId}
  AND active_pull_attempt_id = #{binding.attemptId}
  AND pull_call_id = #{binding.pullCallId}

UPDATE pull_task_group_account SET membership_status = #{transition.target.status}, membership_failure_count = #{transition.target.failureCount}, pull_call_id = #{transition.target.pullCallId}, active_pull_attempt_id = #{transition.target.activeAttemptId}, membership_reason_code = #{transition.result.reasonCode}, membership_reason_message = #{transition.result.reasonMessage}, membership_result_at = #{transition.result.occurredAt}, joined_at =
COALESCE(#{transition.result.occurredAt}, joined_at)
joined_at , updated_at = #{transition.scope.now} WHERE id = #{transition.scope.participantId} AND active_pull_attempt_id = #{transition.scope.attemptId} AND membership_failure_count = #{transition.expected.failureCount} AND membership_status IN #{status}

UPDATE pull_task_group_account
SET membership_status = #{transition.target.status},
    pull_call_id = #{transition.target.pullCallId},
    active_pull_attempt_id = CASE
      WHEN active_pull_attempt_id = #{transition.scope.attemptId}
        THEN #{transition.target.activeAttemptId}
      ELSE active_pull_attempt_id
    END,
    membership_reason_code = NULL,
    membership_reason_message = NULL,
    membership_result_at = #{transition.result.occurredAt},
    joined_at = COALESCE(#{transition.result.occurredAt}, joined_at),
    updated_at = #{transition.scope.now}
WHERE id = #{transition.scope.participantId}
  AND membership_status <> #{transition.target.status}

